			function filterDsAuthGrp() {
			    
			    var dsAuthGrp = app.lookup("dsAuthGrp");
			    var ds2 = app.lookup("dsSelectedAuthGrp");
			    
			    var ipb2 = app.lookup("ipb2");
			    var cmb1 = app.lookup("cmb1");
			    var ipb4 = app.lookup("ipb4");
			    var cmb2 = app.lookup("cmb2");
			    
			    var filterStr = "";
			    
			    //if (ipb5.displayText != null && ipb5.displayText.trim() != "") {
			        
			    //}
			    //console.log("ipb17", ipb17.value);
			    //console.log("ipb17", ipb17.displayText);
			    //console.log("ipb18", ipb18.value);

			    var findRows = ds2.getRowDataRanged();
			    var filterStr = "";
			    for (var i=0; i < findRows.length; i++) {
			        if (i > 0) {
			            filterStr += " and ";
			        }
			        filterStr += "AUTHRT_ID != '" + findRows[i].AUTHRT_ID + "'";
			    }
			        
			    
			    if (ipb2.displayText != null && ipb2.displayText != "") {
			        if (filterStr == "") {
			            filterStr = "AUTHRT_NM *= '" + ipb2.displayText + "'";
			        } else {
			            filterStr += " and AUTHRT_NM *= '" + ipb2.displayText + "'";
			        }
			    }
			    
			    if (cmb1.value != null && cmb1.value != "") {
			        if (filterStr == "") {
			            filterStr = "INST_TYPE_SE_CD == '" + cmb1.value + "'";
			        } else {
			            filterStr += " and INST_TYPE_SE_CD == '" + cmb1.value + "'";
			        }
			    }
			    
			//    if (ipb4.displayText != null && ipb4.displayText != "") {
			//        if (filterStr == "") {
			//            filterStr = "INST_NM *= '" + ipb4.displayText + "'";
			//        } else {
			//            filterStr += " and INST_NM *= '" + ipb4.displayText + "'";
			//        }
			//    }
			    
			    //console.log("filterStr", filterStr);
			    if (filterStr == "") {
			        dsAuthGrp.clearFilter();
			    } else {
			        dsAuthGrp.setFilter(filterStr);
			    }
			}


